def isBalancedCode(s):
    closer = {')': '(', ']': '[', '}': '{'}
    stack = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == "'" or c == '"':
            i += 1
            while i < n and s[i] != c:
                if s[i] == '\\':
                    i += 1
                i += 1
            if i >= n:
                return False
            i += 1
        else:
            if c in '([{':
                stack.append(c)
            elif c in closer:
                if not stack or stack.pop() != closer[c]:
                    return False
            i += 1
    return not stack
